void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  float lod = floor(uv.x * 4.0);
  vec3 a = textureLod(iChannel0, vec3(uv * 3.0, 0.25), lod).rgb;
  vec3 b = texelFetch(iChannel0, ivec3(int(uv.x * 32.0), int(uv.y * 32.0), 5), 0).rgb;
  fragColor = vec4(mix(a, b, step(0.5, uv.y)), 1.0);
}
